(()=>{const f=facilities.find(x=>x.id==='moe_1010017');if(!f)return;const source='https://www.town.tamamura.lg.jp/docs/2023061600017/file_contents/teirei5_0901.pdf';const note='玉村町議会令和5年第3回定例会会議録41頁、環境安全課長が当初竣工時の建設施工者は株式会社タクマと明言。1990年建設の当初施設に関する証言で、2001年排ガス改造や2023年年次整備の受注とは区別。';if(!f.builder){f.builder='株式会社タクマ';f.builder_source=source;f.builder_scope=note;f.builder_research_status='一次資料確認済み・当初建設施工';}else{f.builder_additional_research_note=[f.builder_additional_research_note,note].filter(Boolean).join(' ／ ');f.builder_additional_research_urls=[f.builder_additional_research_urls,source].filter(Boolean).join(' | ');}})();